class ROOT(object):
    """ROOT references the root (original) target in nested specs.

    :class:`ROOT` is useful when you're deep inside a nested spec and
    need to reference the original input data.

    >>> target = {'a': {'b': {'c': 1}}}
    >>> glom(target, {'val': 'a.b.c', 'root_keys': ('ROOT', lambda r: list(r.keys()))})
    {'val': 1, 'root_keys': ['a']}

    >>> target = [1, 2, 3]
    >>> glom(target, [lambda x: {'val': x, 'total': (ROOT, sum)}])
    [{'val': 1, 'total': 6}, {'val': 2, 'total': 6}, {'val': 3, 'total': 6}]

    .. note::
       ROOT is implemented as a T expression that always refers to the
       outermost target, regardless of nesting level.

    """
    def __init__(self):
        pass

    def glomit(self, target, scope):
        # Return the root target stored at the top level
        # In glom, T is set to the current target, so we need to track root separately
        # We use a special marker in scope
        return scope.get(_ROOT_MARKER, target)

    def __call__(self, *args, **kwargs):
        # Allow method chaining on ROOT
        return ROOT()

    def __getattr__(self, name):
        # Support attribute access like ROOT.keys()
        return ROOT()

    def __getitem__(self, key):
        # Support item access like ROOT['key']
        return ROOT()

    def __repr__(self):
        return 'ROOT'


# Add ROOT marker to scope
_ROOT_MARKER = make_sentinel('_ROOT_MARKER')
